  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f06', 'da-nang', 'cam-le', 6, 'budget', st_multi(ST_GeomFromGeoJSON('{"type":"MultiPolygon","coordinates":[[[[108.2023298,16.0050434],[108.1984482,16.0023316],[108.1894151,15.9989573],[108.1844883,15.993856],[108.1840655,15.9857437],[108.1861415,15.983931],[108.1851304,15.9820384],[108.1858599,15.981649],[108.1855273,15.980548],[108.1840199,15.9782337],[108.1845108,15.9767111],[108.1834252,15.9755443],[108.1840454,15.9752935],[108.1816281,15.9652875],[108.186447,15.9655415],[108.1862274,15.9644391],[108.1873056,15.9641064],[108.1864467,15.9622033],[108.1905363,15.9620486],[108.1900822,15.9609287],[108.1910295,15.96095],[108.1914168,15.9627629],[108.1951327,15.9629289],[108.1952074,15.9641844],[108.1973639,15.9644829],[108.1979547,15.963006],[108.2028785,15.9638666],[108.2047641,15.9605438],[108.2034672,15.9571468],[108.2054803,15.9547143],[108.2045898,15.9529891],[108.2045663,15.9514307],[108.2056023,15.9511064],[108.2046702,15.9486539],[108.2059979,15.9468357],[108.2095358,15.9451774],[108.2105094,15.9427118],[108.2164438,15.9461316],[108.2161193,15.9493218],[108.217793,15.9494475],[108.2178386,15.9472664],[108.2197215,15.9459214],[108.2226846,15.9474791],[108.2218092,15.9499712],[108.2244456,15.9561285],[108.2247949,15.9602976],[108.2236315,15.9619971],[108.2196131,15.9643303],[108.2168795,15.9716436],[108.2227105,15.9799469],[108.2205944,15.9872783],[108.2280323,15.9907624],[108.2294794,15.9925574],[108.2290955,16.001092],[108.2327005,16.0065582],[108.233214,16.0117633],[108.2395077,16.0202503],[108.2383731,16.0242939],[108.2350589,16.0291604],[108.2258911,16.0267248],[108.2191762,16.0202206],[108.2151979,16.0176673],[108.2091609,16.0103882],[108.2023298,16.0050434]]],[[[108.221327,16.0224955],[108.2151979,16.0176673],[108.211018,16.0122553],[108.2054682,16.0072359],[108.1984482,16.0023316],[108.1894151,15.9989573],[108.1851779,15.9941246],[108.1673795,15.9934249],[108.1601285,15.9949611],[108.1582968,15.9941207],[108.1577182,