insert into public.district_localizations (district_id, language, name, area, rent_range, distance_to_beach, summary, best_for)
values
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f01', 'ru', 'Полуостров: Микхе и тихий север', '7-15 млн ₫', '5-10 мин пешком до моря', 'Полуостров в первой линии: пляж Микхе, кафе и спортзалы в шаге, серф для новичков с апреля по август. Самые высокие цены и шум в сезон; зато север полуострова - зелёный, тихий, с портовым характером.', '{beach,nightlife,expat}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f01', 'en', 'The peninsula: My Khe and the quiet north', '7-15M VND', '5-10 min walk to the sea', 'The beachfront peninsula: My Khe, cafes and gyms in walking distance, beginner surf from April to August. The highest prices and seasonal noise; the northern tip, though, is green, quiet and port-flavoured.', '{beach,nightlife,expat}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f02', 'ru', 'Юго-восток: Бак Ми Ан, Хоа Хай, FPT City', 'студия 5-8 млн, 1BR 8-13 млн ₫', 'пляж Нон Нуок 8 мин на байке', 'Новый Дананг: с 2022 года юг растёт башнями 25-40 этажей (FPT Plaza, Sunrise Bay, The Filmore) с бассейнами и охраной. Лучшее соотношение цены и новизны; пляж Нон Нуок длиннее и тише Микхе, Мраморные горы рядом, международные школы в радиусе 3 км. Квартал FPT City у университета - недорогое жильё для студентов и айтишников. Без байка туго: до Ан Тхыонг 25 минут.', '{family,budget,expat}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f02', 'en', 'South-east: Bac My An, Hoa Hai, FPT City', 'studio 5-8M, 1BR 8-13M VND', 'Non Nuoc beach 8 min by bike', 'The new Da Nang: since 2022 the south has grown 25-40 floor towers (FPT Plaza, Sunrise Bay, The Filmore) with pools and security. The best price-to-newness ratio; Non Nuoc beach is longer and quieter than My Khe, Marble Mountains nearby, international schools within 3 km. The FPT City quarter by the university offers affordable housing for students and IT folks. You really want a bike: An Thuong is 25 minutes away.', '{family,budget,expat}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f03', 'ru', 'Центр и набережная Хан', 'студия 4-6 млн, 1BR 6-10 млн ₫', '10 мин на байке до Микхе', 'Настоящий Дананг без туристической упаковки: рынок Хан, банки, офисы, Розовый собор и музей чамской скульптуры. Дешёвая местная еда, по-английски почти не говорят. До пляжа Микхе 10 минут на байке.', '{budget,markets,family}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f03', 'en', 'Center and the Han riverfront', 'studio 4-6M, 1BR 6-10M VND', '10 min by bike to My Khe', 'Da Nang as locals live it: Han market, banks, offices, the Pink Cathedral and the Cham sculpture museum. Cheap local food, little English spoken. My Khe beach is 10 minutes away by bike.', '{budget,markets,family}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f04', 'ru', 'Thanh Khê', 'Запад от центра', '4-6 млн ₫/мес', '10-15 мин на байке до пляжа', 'Местная жизнь без туристов. Свой пляж - подальше от туристических толп.),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f04', 'en', 'Thanh Khê', 'West of the center', '4-6M ₫/mo', '10-15 min by bike to the beach', 'Local life without tourists. Its own beach away from the crowds.),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f05', 'ru', 'Север: Хоа Кхань, Нам О, перевал Хайван', 'студия 2,5-4,5 млн ₫', 'дикий пляж Nam О 25 мин', 'Промышленный север с самыми низкими ценами в городе: студия от 2,5 млн ₫, дикий рыбацкий пляж Nam О, студенты и бюджетные зимовщики. Коворкингов и англоязычной среды почти нет, ночью шумят фуры - но до центра 20 минут.', '{budget,quiet}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f05', 'en', 'North: Hoa Khanh, Nam O, Hai Van pass', 'studio 2.5-4.5M VND', 'wild Nam O beach 25 min', 'The industrial north with the lowest prices in town: studios from 2.5M VND, the wild fishing beach Nam O, students and long-term budget stayers. Almost no coworkings or English-speaking scene, trucks rumble at night - but the center is 20 minutes away.', '{budget,quiet}),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f06', 'ru', 'Cẩm Lệ', 'Юг, за центром', '4-6 млн ₫/мес', '20-25 мин на байке до моря', 'Новые дома и локальные цены. Для жизни с байком, не для отпуска у моря.),
  ('b937c18f-2b7e-4a5a-8f3d-9a1c5d6e8f06', 'en', 'Cẩm Lệ', 'South, behind the center', '4-6M ₫/mo', '20-25 min by bike to the sea', 'New buildings at local prices. For living with a bike, not a beach holiday.)
